   310  void bn_read_str(bn_t a, const char *str, int len, int radix) {
   311          int sign, i, j;
   312          char c;
   313
   314          bn_zero(a);
   315
   316          if (radix < 2 || radix > 64) {
   317                  RLC_THROW(ERR_NO_VALID);
   318                  return;
   319          }
   320
   321          j = 0;
   322          if (str[0] == '-') {
   323                  j++;
   324                  sign = RLC_NEG;
   325          } else {
   326                  sign = RLC_POS;
   327          }
   328
   329          RLC_TRY {
   330                  bn_grow(a, RLC_CEIL(len * util_bits_dig(radix), RLC_DIG));
   331
   332                  while (j < len) {
   333                          if (str[j] == 0) {
   334                                  break;
   335                          }
   336                          c = (char)((radix < 36) ? RLC_UPP(str[j]) : str[j]);
   337                          for (i = 0; i < 64; i++) {
   338                                  if (c == util_conv_char(i)) {
   339                                          break;
   340                                  }
   341                          }
   342
   343                          if (i < radix) {
   344                                  bn_mul_dig(a, a, (dig_t)radix);
   345                                  bn_add_dig(a, a, (dig_t)i);
   346                          } else {
   347                                  break;
   348                          }
   349                          j++;
   350                  }
   351
   352                  a->sign = sign;
   353          } RLC_CATCH_ANY {
   354                  RLC_THROW(ERR_CAUGHT);
   355          }
