   358  void bn_write_str(char *str, int len, const bn_t a, int radix) {
   359          bn_t t;
   360          dig_t d;
   361          int digits, l, i, j;
   362          char c;
   363
   364          bn_null(t);
   365
   366          l = bn_size_str(a, radix);
   367          if (len < l) {
   368                  RLC_THROW(ERR_NO_BUFFER);
   369                  return;
   370          }
   371
   372          if (radix < 2 || radix > 64) {
   373                  RLC_THROW(ERR_NO_VALID);
   374                  return;
   375          }
   376
   377          if (bn_is_zero(a) == 1) {
   378                  *str++ = '0';
   379                  *str = '\0';
   380                  return;
   381          }
   382
   383          RLC_TRY {
   384                  bn_new(t);
   385                  bn_copy(t, a);
   386
   387                  j = 0;
   388                  if (t->sign == RLC_NEG) {
   389                          str[j] = '-';
   390                          j++;
   391                          t->sign = RLC_POS;
   392                  }
   393
   394                  digits = 0;
   395                  while (!bn_is_zero(t) && j < len) {
   396                          bn_div_rem_dig(t, &d, t, (dig_t)radix);
   397                          str[j] = util_conv_char(d);
   398                          digits++;
   399                          j++;
   400                  }
   401
   402                  /* Reverse the digits of the string. */
   403                  i = 0;
   404                  if (str[0] == '-') {
   405                          i = 1;
   406                  }
   407
   408                  j = l - 2;
   409                  while (i < j) {
   410                          c = str[i];
   411                          str[i] = str[j];
   412                          str[j] = c;
   413                          ++i;
   414                          --j;
   415                  }
   416
   417                  str[l - 1] = '\0';
   418          }
   419          RLC_CATCH_ANY {
   420                  RLC_THROW(ERR_CAUGHT);
   421          }
   422          RLC_FINALLY {
   423                  bn_free(t);
   424          }
   425  }
