   427  int bn_size_bin(const bn_t a) {
   428          dig_t d;
   429          int digits;
   430
   431          digits = (a->used - 1) * (RLC_DIG / 8);
   432          d = a->dp[a->used - 1];
   433
   434          while (d != 0) {
   435                  d = d >> 8;
   436                  digits++;
   437          }
   438          return digits;
   439  }
