dig_t bn_sub1_low(dig_t *c, const dig_t *a, dig_t digit, int size) {
        int i;
        dig_t carry, r0;

        carry = digit;
        for (i = 0; i < size && carry; i++, c++, a++) {
                r0 = (*a) - carry;
                carry = (r0 > (*a));
                (*c) = r0;
        }
        for (; i < size; i++, a++, c++) {
                (*c) = (*a);
        }
